import { createFileRoute, Outlet } from '@tanstack/react-router'
import { useAuth } from '@/hooks/useAuth'
import { LayoutDashboard, Calendar, Ticket, QrCode, IndianRupee, Users, Settings, LogOut } from 'lucide-react'
import { toast } from 'sonner'

export const Route = createFileRoute('/admin/_layout')({
  component: AdminLayout,
})

const navItems = [
  { label: 'Dashboard', href: '/admin', icon: LayoutDashboard },
  { label: 'Events', href: '/admin/events', icon: Calendar },
  { label: 'Registrations', href: '/admin/registrations', icon: Ticket },
  { label: 'Check-In', href: '/admin/check-in', icon: QrCode },
  { label: 'Payments', href: '/admin/payments', icon: IndianRupee },
  { label: 'Users', href: '/admin/users', icon: Users },
  { label: 'Societies', href: '/admin/societies', icon: Settings },
]

function AdminLayout() {
  const { user, isLoading, signOut } = useAuth()

  if (isLoading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-ieee-blue border-t-transparent" />
      </div>
    )
  }

  if (!user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-muted/30">
        <div className="text-center">
          <h2 className="text-xl font-bold">Admin Access Required</h2>
          <p className="mt-2 text-sm text-muted-foreground">
            Please sign in with your Google account to access the admin panel.
          </p>
          <a
            href="/"
            className="mt-4 inline-block rounded-md bg-ieee-blue px-6 py-2 text-sm font-medium text-white hover:bg-ieee-light-blue"
          >
            Go to Home
          </a>
        </div>
      </div>
    )
  }

  return (
    <div className="flex min-h-screen bg-muted/30">
      {/* Sidebar */}
      <aside className="fixed inset-y-0 left-0 w-64 border-r bg-background">
        <div className="flex h-16 items-center border-b px-6">
          <span className="font-bold text-ieee-blue">Admin Panel</span>
        </div>
        <nav className="space-y-1 p-4">
          {navItems.map((item) => {
            const Icon = item.icon
            return (
              <a
                key={item.href}
                href={item.href}
                className="flex items-center gap-3 rounded-md px-4 py-2.5 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                <Icon className="h-4 w-4" />
                {item.label}
              </a>
            )
          })}
        </nav>
        <div className="absolute bottom-0 w-full border-t p-4">
          <button
            onClick={() => {
              signOut()
              toast.info('Signed out')
            }}
            className="flex w-full items-center gap-3 rounded-md px-4 py-2.5 text-sm font-medium text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            <LogOut className="h-4 w-4" />
            Sign out
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="ml-64 flex flex-1 flex-col">
        <header className="flex h-16 items-center justify-between border-b bg-background px-8">
          <h1 className="font-semibold">Dashboard</h1>
          <div className="flex items-center gap-3">
            <span className="text-sm">{user.name}</span>
            <span className="rounded-full bg-ieee-blue/10 px-2 py-0.5 text-xs font-medium text-ieee-blue">
              {user.role}
            </span>
          </div>
        </header>
        <main className="flex-1 p-8">
          <Outlet />
        </main>
      </div>
    </div>
  )
}
